-- 44 ledger entries, two per ledger transaction.
-- Debit = negative, credit = positive; each ledger transaction sums to 0.

INSERT INTO ledger_entries (ledger_transaction_id, account_id, amount, created_at)
SELECT lt.id, e.account_id::UUID, e.amount, lt.created_at
FROM (VALUES
    -- Deposits: settlement account -> customer wallet of the same currency
    ('d0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001',  -5000.00),
    ('d0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000004',   5000.00),
    ('d0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000002',  -2000.00),
    ('d0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000005',   2000.00),
    ('d0000000-0000-0000-0000-000000000003', 'b0000000-0000-0000-0000-000000000003', -50000.00),
    ('d0000000-0000-0000-0000-000000000003', 'b0000000-0000-0000-0000-000000000006',  50000.00),
    ('d0000000-0000-0000-0000-000000000004', 'b0000000-0000-0000-0000-000000000001',  -3000.00),
    ('d0000000-0000-0000-0000-000000000004', 'b0000000-0000-0000-0000-000000000007',   3000.00),
    ('d0000000-0000-0000-0000-000000000005', 'b0000000-0000-0000-0000-000000000002',  -1500.00),
    ('d0000000-0000-0000-0000-000000000005', 'b0000000-0000-0000-0000-000000000008',   1500.00),
    ('d0000000-0000-0000-0000-000000000006', 'b0000000-0000-0000-0000-000000000003', -40000.00),
    ('d0000000-0000-0000-0000-000000000006', 'b0000000-0000-0000-0000-000000000010',  40000.00),
    ('d0000000-0000-0000-0000-000000000007', 'b0000000-0000-0000-0000-000000000001',  -1000.00),
    ('d0000000-0000-0000-0000-000000000007', 'b0000000-0000-0000-0000-000000000009',   1000.00),
    ('d0000000-0000-0000-0000-000000000008', 'b0000000-0000-0000-0000-000000000003', -20000.00),
    ('d0000000-0000-0000-0000-000000000008', 'b0000000-0000-0000-0000-000000000012',  20000.00),
    ('d0000000-0000-0000-0000-000000000009', 'b0000000-0000-0000-0000-000000000002',   -500.00),
    ('d0000000-0000-0000-0000-000000000009', 'b0000000-0000-0000-0000-000000000013',    500.00),
    -- Transfers between users
    ('d0000000-0000-0000-0000-000000000010', 'b0000000-0000-0000-0000-000000000004',   -250.00),
    ('d0000000-0000-0000-0000-000000000010', 'b0000000-0000-0000-0000-000000000007',    250.00),
    ('d0000000-0000-0000-0000-000000000011', 'b0000000-0000-0000-0000-000000000007',   -100.00),
    ('d0000000-0000-0000-0000-000000000011', 'b0000000-0000-0000-0000-000000000009',    100.00),
    ('d0000000-0000-0000-0000-000000000012', 'b0000000-0000-0000-0000-000000000006',  -1200.00),
    ('d0000000-0000-0000-0000-000000000012', 'b0000000-0000-0000-0000-000000000010',   1200.00),
    ('d0000000-0000-0000-0000-000000000013', 'b0000000-0000-0000-0000-000000000010',   -800.00),
    ('d0000000-0000-0000-0000-000000000013', 'b0000000-0000-0000-0000-000000000012',    800.00),
    ('d0000000-0000-0000-0000-000000000014', 'b0000000-0000-0000-0000-000000000008',    -75.50),
    ('d0000000-0000-0000-0000-000000000014', 'b0000000-0000-0000-0000-000000000005',     75.50),
    ('d0000000-0000-0000-0000-000000000015', 'b0000000-0000-0000-0000-000000000012',   -150.00),
    ('d0000000-0000-0000-0000-000000000015', 'b0000000-0000-0000-0000-000000000010',    150.00),
    ('d0000000-0000-0000-0000-000000000016', 'b0000000-0000-0000-0000-000000000005',   -100.00),
    ('d0000000-0000-0000-0000-000000000016', 'b0000000-0000-0000-0000-000000000008',    100.00),
    -- Withdrawals: customer wallet -> settlement account of the same currency
    ('d0000000-0000-0000-0000-000000000020', 'b0000000-0000-0000-0000-000000000004',   -400.00),
    ('d0000000-0000-0000-0000-000000000020', 'b0000000-0000-0000-0000-000000000001',    400.00),
    ('d0000000-0000-0000-0000-000000000021', 'b0000000-0000-0000-0000-000000000007',   -150.00),
    ('d0000000-0000-0000-0000-000000000021', 'b0000000-0000-0000-0000-000000000001',    150.00),
    ('d0000000-0000-0000-0000-000000000022', 'b0000000-0000-0000-0000-000000000010',  -5000.00),
    ('d0000000-0000-0000-0000-000000000022', 'b0000000-0000-0000-0000-000000000003',   5000.00),
    -- Refunds
    ('d0000000-0000-0000-0000-000000000025', 'b0000000-0000-0000-0000-000000000007',    -50.00),
    ('d0000000-0000-0000-0000-000000000025', 'b0000000-0000-0000-0000-000000000004',     50.00),
    ('d0000000-0000-0000-0000-000000000026', 'b0000000-0000-0000-0000-000000000001',   -150.00),
    ('d0000000-0000-0000-0000-000000000026', 'b0000000-0000-0000-0000-000000000007',    150.00),
    ('d0000000-0000-0000-0000-000000000027', 'b0000000-0000-0000-0000-000000000007',    -25.00),
    ('d0000000-0000-0000-0000-000000000027', 'b0000000-0000-0000-0000-000000000004',     25.00)
) AS e (operation_id, account_id, amount)
JOIN ledger_transactions lt ON lt.operation_id = e.operation_id::UUID;
